//my files
class AjaxFormSubmit {

  constructor(element, options) {
    this._elements = document.querySelectorAll(element);
    this._setParams(options);
    this._run();
  }

  _setParams(options) {
    this._debug = options.debug || false;
    this._callback = options.callback || null;
  }

  _run() {
    this._elements.forEach((form) => {
      form.addEventListener('submitAfterValidate', (event) => {
        event.preventDefault();
        
        let data = new FormData(form);
        let action = form.action;
        let method = form.method;

        let csrfToken = document.head.querySelector("[name=csrf-token]")?.content;

        let request = new XMLHttpRequest();
        request.open(method, action);
        if (csrfToken != null) request.setRequestHeader("X-CSRF-TOKEN", csrfToken);
        // request.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
        request.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
        request.send(data);
        
        request.addEventListener('load', () => {
          if (request.status === 200) {
            if (this._callback != null) this._callback(form, true);
            if (this._debug) console.log('Form Submit Successfully');
          } else {
            if (this._debug) console.error('Something went wrong');
          }
        });
        request.addEventListener('error', () => {
          if (this._debug) console.error('Error submitting form');
        });

      });
    });
  }

}
function lockBody() {
	$('body').addClass('no-scroll');

    let scrollbarWidth = getScrollbarWidth()

    $('body').css('padding-right', scrollbarWidth)
    $('[data-js="siteHeader"]').css('padding-right', scrollbarWidth)
}

function unlockBody() {
	$('body').removeClass('no-scroll');
    $('body').css('padding-right', 0);
    $('[data-js="siteHeader"]').css('padding-right', 0)
}

function getScrollbarWidth() {
    let div = document.createElement('div');

    div.style.overflowY = 'scroll';
    div.style.width = '50px';
    div.style.height = '50px';

    document.body.append(div);
    let scrollWidth = div.offsetWidth - div.clientWidth;

    div.remove();

    return scrollWidth
}

const jsTemplatePath = (typeof SITE_TEMPLATE_PATH !== 'undefined' && SITE_TEMPLATE_PATH ? SITE_TEMPLATE_PATH + '/' : '');

document.addEventListener('DOMContentLoaded', () => {
    searchInit();
    sectionBgSlider();
    fancyboxInit();
})

// Фоновый слайдер
function sectionBgSlider() {
    const sectionBgSliders = document.querySelectorAll('[data-js="sectionBgSlider"]')

    if(sectionBgSliders.length < 1) return

    sectionBgSliders.forEach(slider => {
        const sliderEx = new Swiper(slider, {
            slidesPerView: 1,
            loop: true,
            speed: 1000
        })
    })
}

function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Инициализация фансибокса
function fancyboxInit() {
    Fancybox.bind("[data-fancybox]", {
        placeFocusBack: false,
        mainClass: 'my-fancybox',
        idle: false,
        Carousel: {
            transition: "crossfade",
            Navigation: {
                prevTpl: '<svg><use xlink:href="'+jsTemplatePath+'img/sprites/sprite.svg#arrow_fancy_left"></use></svg>',
                nextTpl: '<svg><use xlink:href="'+jsTemplatePath+'img/sprites/sprite.svg#arrow_fancy_right"></use></svg>',
              },
        },
        Thumbs: {
            type: "classic",
        },
        Toolbar: {
            enabled: true,
            display: {
                left: [],
                middle: [],
                right: [
                  "close",
                ],
            },
        }

    });
}

// Поиск
function searchInit() {
    const searchForms = document.querySelectorAll('[data-js="menuSearch"]')

    if(!searchForms.length) return

    searchForms.forEach((searchForm, index) => {
        let results = searchForm.querySelector('[data-js="menuSearchResults"]')
        let resultsID = 'menuSearchResults' + index
        results.setAttribute('id', resultsID)

        const autoCompleteJS = new autoComplete({
              selector: () => {
                    return searchForm.querySelector("[data-js='autoCompleteSearch']");
                }, 
              submit: true,
              debounce: 300,
              data: {
                  src: async (query) => {
                    try {
                      const source = await fetch(`https://df-mdf.ru/catalog/search.json?term=${query}`);
                      const data = await source.json();
              
                      return data;
                    } catch (error) {
                      return error;
                    }
                  },
                  cache: false,
                  keys: ["label"],
              },
              resultsList: {
                    destination: '#' + resultsID,
                    position: "beforeend",
                    tag: 'div',
                    class: "search-results",
                    element: (list, data) => {
                        if (!data.results.length) {
                            const message = document.createElement("div");
                            message.setAttribute("class", "no_result");
                            message.innerHTML = `<span>Возможно позиция выведена, обратитесь к Вашему офис-менеджеру</span>`;
                            list.prepend(message);
                        }
                    },
                    noResults: true,
              },
              resultItem: {
                  highlight: true,
                  element: (list, data) => {
                    list.classList.add('order-prod', 'search-results__item')
                    list.innerHTML = ''

                    const imgContainer = document.createElement('div')
                    imgContainer.classList.add('order-prod__img')

                    const img = document.createElement('img');
                    img.src=data.image;

                    imgContainer.appendChild(img)
                    list.appendChild(imgContainer)
                    
                    const info = document.createElement('div')
                    info.classList.add('order-prod__info')

                    const title = document.createElement('a')
                    title.href = data.value;
                    title.innerHTML = data.label.trim();
                    title.classList.add('order-prod__title')
                    info.appendChild(title)

                    // добавить цену
                    //const text = document.createElement('div')
                    //text.innerHTML = data.....trim();
                    //text.classList.add('order-prod__text')
                    //info.appendChild(text)

                    list.appendChild(info)
                  }
              },
              events: {
                input: {
                    selection(event) {
                        const feedback = event.detail;
                        const input = autoCompleteJS.input;
                        const selection = feedback.selection.value['label'].trim();
                        previous_search_query = JSON.parse(window.sessionStorage.getItem('search_results') );
                        if (previous_search_query === null) {
                          window.sessionStorage.setItem('search_results', JSON.stringify(selection.split(",")) );
                        } else {
                          previous_search_query.push(selection);
                          window.sessionStorage.setItem('search_results', JSON.stringify(previous_search_query) );  
                        }
                        location.href = event.detail.selection.value['value'];
                    }
                },
              }
        });
    })
    

}
function selects() {
	const formSelects = document.querySelectorAll("[data-js='formSelect']")

	formSelects.forEach(formSelect => {
		let placeholder = $(formSelect).attr('data-placeholder')
		let clear = $(formSelect).attr('data-clear')
		let allowClear = clear === 'true' ? true : false

		if(formSelect.hasAttribute('data-filterable')) {
			$(formSelect).select2({
				placeholder: placeholder,
				allowClear: allowClear,
				templateResult: function (data) {
					if(data.element && $(data.element).hasClass('disabled')) {
						return null;
					}
					return data.text;
				}
			});
		} else {
			$(formSelect).select2({
				placeholder: placeholder,
				allowClear: allowClear
			});
		}
	}) 

	$("[data-js='formSelect']").on('select2:open', () => {
		$(".select2-dropdown").addClass("select2-dropdown--form")
	})

}

function reloadSelect(formSelect) {
	if(formSelect) {
		let placeholder = $(formSelect).attr('data-placeholder')
		let allowClear = clear === 'true' ? true : false
		$(formSelect).select2('destroy');
		if(formSelect.hasAttribute('data-filterable')) {
			$(formSelect).select2({
				placeholder: placeholder,
				allowClear: allowClear,
				templateResult: function (data) {
					if(data.element && $(data.element).hasClass('disabled')) {
						return null;
					}
					return data.text;
				}
			});
		} else {
			$(formSelect).select2({
				placeholder: placeholder,
				allowClear: allowClear
			});
		}
	}
}
function validation() {

    let forms = document.querySelectorAll('[data-validate]')
    forms = [ ...forms].filter(item => !item.hasAttribute('data-validated'))

    if (!forms.length) return


    forms.forEach(form => {

        inputMasksInit(form);
        form.setAttribute('data-validated', '')

        form.addEventListener('submit', event => {
            event.preventDefault()

            const inputFields = form.querySelectorAll('[data-js="formField"]');

            const dataReqexp = {
                email: /^([A-Za-z0-9_\-\.])+\@([A-Za-z0-9_\-\.])+\.([A-Za-z]{2,})$/,
                space: /^(\s)+$/,
                date: /([0-9]{2})\.([0-9]{2})\.([0-9]{4})/
            }

            function error(el, errorText = "") {
                let errorField = el.querySelector("[data-js='fieldError']")
                return {
                    set: () => {
                        el.classList.add("field--invalid")
                        errorField.innerHTML = errorText
                    },
                    remove: () => {
                        el.classList.remove("field--invalid")
                        errorField.innerHTML = errorText
                    },
                }
            }

            function validateInput(input) {
                const field = input.querySelector('input') ? input.querySelector('input') : input.querySelector('textarea') ? input.querySelector('textarea') : input.querySelector('select')

                if(!field) return

                const name = field.getAttribute('data-v-name');
                let valueField = name === "file" ? field.files : field.value;
                let spaceTrigger = name === "file" ? true : !valueField.match(dataReqexp.space);

                if (field.hasAttribute('required') && !field.hasAttribute('disabled')) {
                    if (valueField !== '' && spaceTrigger) {
                        switch (name) {
                            case 'email':
                                if (valueField.match(dataReqexp.email)) {
                                    error(input).remove()
                                } else {
                                    error(input, 'Некорректный email').set()
                                }
                                break
                            case 'phone':
                                valueField = valueField.replace(/\D/g, "")

                                if (valueField.length === 11) {
                                    error(input).remove()
                                } else {
                                    error(input, 'Некорректный номер телефона').set()
                                }
                                break                              
                            case 'checkbox':
                                if (field.checked) {
                                    error(input).remove()
                                } else {
                                    error(input, 'Необходимо согласие').set()
                                }
                                break                            
                            default:
                                if (valueField.length !== 0) {
                                    error(input).remove()
                                } else {
                                    error(input, "Необходимо заполнить это поле").set()
                                }
                        }
                    } else {
                        error(input, 'Необходимо заполнить это поле').set()
                    }
                }
            }

            function checkFields() {
            
                inputFields.forEach(input => {
                    validateInput(input)
                })
            }

            function lifeValidate() {
                inputFields.forEach(input => {
                    input.addEventListener('click', () => {
                        if (form.getAttribute('data-validate')) {
                            const field = input.querySelector('input') ? input.querySelector('input') : input.querySelector('textarea') ? input.querySelector('textarea') : input.querySelector('select')

                            if(!field) return

                            field.addEventListener('input', () =>
                                validateInput(input),
                            )

                            checkFields()

                            if(field.dataset.js === 'formSelect') {
                                field.closest('[data-js="formField"]').classList.remove('field--invalid')
                            }

                        }
                    })
                })
            }

            function validate() {
                let errors = 0

                inputFields.forEach(input => {
                    if (input.classList.contains('field--invalid')) {
                        errors += 1
                    }
                })

                // тут отправляем данные
                if (errors === 0) {
                    toggleLoading(form, true)
                    const submitEvent = new Event('submitAfterValidate', {
                        bubbles: false,
                        cancelable: true
                    });
                    form.dispatchEvent(submitEvent);
                }
            }

            lifeValidate()
            checkFields()
            form.setAttribute('data-validate', 'true')

            validate()

        })
    })
}

function toggleLoading(form, on) {
    const formSubmitBtn = form.querySelector(".d-btn.form__submit")

    if(on) {
        const loadingIcon = document.createElement('span')
        loadingIcon.classList.add('load-icon')
        loadingIcon.innerHTML = `<svg fill="none" height="24" viewBox="0 0 48 48" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M4 24C4 35.0457 12.9543 44 24 44C35.0457 44 44 35.0457 44 24C44 12.9543 35.0457 4 24 4" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="4"/></svg>`

        formSubmitBtn.appendChild(loadingIcon)
        formSubmitBtn.classList.add('loading')
    } else {
        formSubmitBtn.classList.remove('loading')
        const loadingIcon = formSubmitBtn.querySelector('.load-icon')

        if(loadingIcon) {
            loadingIcon.remove()
        }
    }
}

function inputMasksInit(form) {

    const phones = form.querySelectorAll('input[data-type="phoneNumber"]');
    const letters = form.querySelectorAll('input[data-type="letters"]');

    if(phones.length > 0) {
        phones.forEach(phone => {
            Inputmask({
                'mask': '+7 (999) 999-99-99',
                'showMaskOnHover': false
            }).mask(phone); 
        })
    }

    if(letters.length > 0) {
        letters.forEach(letter => {
            letter.addEventListener('input', function(e){
                
                let val = e.target.value.replace(/[^А-Яа-яA-Za-z\s-]/g, "");
                this.value = val;
            })
        })
    }
}

//включать в случае успешной отправки там, где это требуется
function defaultAfterSubmit(form, doReset) {
    if(doReset===true){
        let fileFields = form.querySelectorAll('.field-file[data-js="formField"]')
        form.reset();

        //сбрасываем поле ФАЙЛ
        if(fileFields.length > 0) {
            fileFields.forEach(fileField => {
                let placeholderText = fileField.getAttribute('data-placeholder');
                let fileName = fileField.querySelector('[data-js="fileName"]');

                fileField.classList.remove('field-file--full');
                fileName.innerHTML = placeholderText;
            });
        }
    }

    //проверяем какой тип благодарности в форме и показываем его
    if(form.querySelector("[data-js='form-thanks']") !== null) {
        form.style.minHeight = form.offsetHeight + 'px'
        form.classList.add("form--sent")
    } else {
        thanksMessageShow();
    }

    toggleLoading(form, false)
}

