function accordion() {
    const accordions = document.querySelectorAll("[data-js='accordion']");

	if(accordions.length < 1) return

	accordions.forEach(accordion => {

		let firstSpoiler = accordion.querySelector('[data-js="spoiler"]')

		if(firstSpoiler) {
			openSpoiler(firstSpoiler)
		}

		accordion.addEventListener('click', (e) => {
			let eventTarget = e.target

			if(eventTarget.closest('[data-js="spoiler"]')) {
				let clickedSpoiler = eventTarget.closest('[data-js="spoiler"]')

				if(clickedSpoiler.classList.contains('active')) {
					return
				}

				let spoilers = accordion.querySelectorAll('[data-js="spoiler"]')

				spoilers.forEach(spoiler => {
					closeSpoiler(spoiler)
				})

				openSpoiler(clickedSpoiler)
			}
		})
	})

	function openSpoiler(spoiler) {
		const content = $(spoiler).find('[data-js="spoilerContent"]');
		spoiler.classList.add("active");
		$(content).slideDown(400);
	};

	function closeSpoiler(spoiler) {
		const content = $(spoiler).find('[data-js="spoilerContent"]');
		spoiler.classList.remove("active");
		$(content).slideUp(400);
	};
}
function sMap() {
    const sMap = document.querySelector('[data-js="sMap"]')

    if(!sMap) return

    const mapEl = sMap.querySelector('[data-js="sMapEl"]')
    const pointsItems = sMap.querySelectorAll('[data-js="sMapItem"]')
    //const pointsList = [... pointsItems].map(item => item.dataset.coords)
    const startCenter = mapEl.dataset.center ? mapEl.dataset.center : '55.883459, 37.444566'
    const startZoom = mapEl.dataset.zoom ? parseInt(mapEl.dataset.center) : 12
	const fullBtn = sMap.querySelector('[data-js="sMapFull"]')
	const mapWrap = sMap.querySelector('[data-js="sMapWrap"]')

    ymaps.ready(async function () {
        let center = startCenter
        let zoom = startZoom
    
        mapEx = new ymaps.Map(mapEl, {
            center: center.replace(/\s/g, '').split(","),
            zoom: zoom,
            controls: []
        }, {
            minZoom: 3,
			autoFitToViewport: 'always'
        });

        renderPoints(pointsItems)

		if(fullBtn && mapWrap) {
			fullBtn.addEventListener('click', () => {
				$(mapWrap).toggleClass('full')
			})
		}

        function renderPoints(items) {
            mapEx.geoObjects.removeAll()
    
            let myGeoObjects = [];
                
            items.forEach((coordsItem, index) => {
                let iconHref = "data:image/svg+xml,%3Csvg width='74' height='74' viewBox='0 0 74 74' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M43.8943 12.6621L61.3379 30.1056C65.1455 33.9132 65.1455 40.0866 61.3379 43.8942L37 68.2321L12.6621 43.8942C8.85452 40.0866 8.85452 33.9132 12.6621 30.1056L30.1057 12.6621C33.9133 8.85445 40.0867 8.85445 43.8943 12.6621Z' fill='white' stroke='url(%23paint0_linear_888_6443)' stroke-width='2.5'/%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M37 19L19 36.5001L37 54L55 36.5001L37 19ZM40.9735 46.9118C40.1628 46.2072 38.211 44.1508 37.7168 40.3414C37.5533 38.9997 36.1559 37.0819 35.2101 36.169C33.4329 34.4533 30.5302 32.9745 25.9555 33.3566C25.8086 33.369 25.6588 33.3833 25.5058 33.4L22.3172 36.5001L37 50.7749L40.9735 46.9118ZM37.6862 36.8607C37.736 36.369 37.8081 35.858 37.9066 35.3267C39.1448 28.6263 35.5501 25.2124 34.6704 24.49L27.0769 31.8725C31.4778 31.7956 34.3886 33.3654 36.2479 35.1599C36.8235 35.7155 37.2989 36.2973 37.6862 36.8607ZM35.712 23.4774C36.6851 24.3137 39.3792 27.053 39.618 31.9374C40.6552 30.6892 42.2618 29.5932 44.6852 29.6968L37 22.2252L35.712 23.4774ZM42.0133 45.9009L51.6828 36.5001L46.4996 31.4609C40.0677 29.6091 38.9591 35.1576 38.9697 38.2796C38.9789 40.889 39.9284 44.1984 42.0133 45.9009Z' fill='url(%23paint1_linear_888_6443)'/%3E%3Cdefs%3E%3ClinearGradient id='paint0_linear_888_6443' x1='20.5' y1='20.5' x2='53.5' y2='53.5' gradientUnits='userSpaceOnUse'%3E%3Cstop stop-color='%23B68C74'/%3E%3Cstop offset='1' stop-color='%23865F46'/%3E%3C/linearGradient%3E%3ClinearGradient id='paint1_linear_888_6443' x1='85.5432' y1='18.98' x2='-5.27436' y2='6.79577' gradientUnits='userSpaceOnUse'%3E%3Cstop stop-color='%23624330'/%3E%3Cstop offset='1' stop-color='%23E7BEA9'/%3E%3C/linearGradient%3E%3C/defs%3E%3C/svg%3E%0A"
                const baloonContacts = coordsItem.getAttribute('data-baloon-contacts')?.replace(', ', ',').replace(',', '<br>')

                let currentPlacemark = new ymaps.Placemark(
                    coordsItem.dataset.coords.replace(/[\[\]]/g, '').split(","),
                    {
                        balloonContentHeader: coordsItem.getAttribute('data-baloon-title'),
                        balloonContentBody:   coordsItem.getAttribute('data-baloon-address'),
                        balloonContentFooter: baloonContacts,
                        hintContent: coordsItem.getAttribute('data-baloon-title')
                    },
                    {
                        openEmptyBalloon: false,
                        iconLayout: 'default#image',
                        iconImageHref: iconHref,
                        iconImageSize: [74, 74],
                        iconImageOffset: [-37, -37],
                    }
                );
    
                
                myGeoObjects.push(currentPlacemark)
            });
    
            var clusterer = new ymaps.Clusterer({
                gridSize: 50,
                preset: 'islands#brownClusterIcons'
            });
    
            clusterer.add(myGeoObjects);
    
            mapEx.geoObjects.add(clusterer);

            if (myGeoObjects.length > 0) {
                mapEx.setBounds(clusterer.getBounds(), {
                    checkZoomRange: true,
                    zoomMargin: 50
                });
            }
    
        }
    })

    pointsItems.forEach((point, i) => {
        setAttributes(point, {
            'data-aos': 'fade-up',
            'data-aos-anchor': `[data-js="sMap"]`,
            'data-aos-duration': '600',
            'data-aos-anchor-placement': 'top-center',
            'data-aos-delay': `${i * 100}`
        })
        
    })

}
function preloader() {
    const preloader = document.querySelector('[data-js="preloader"]')

    if(!preloader) {
        cookieInit();
        return
    }
        

    lockBody()

    const logo = preloader.querySelector('[data-js="preloaderLogo"]')
    const cookieName = 'preloader'
    let currentCookieValue = document.cookie.match(new RegExp("(?:^|; )" + cookieName.replace(/([\.$?*|{}\(\)\[\]\\\/\+^])/g, '\\$1') + "=([^;]*)"));

    if (!currentCookieValue) {
        linesHeight()
        document.cookie = `${cookieName}=true; path=/`
    } else {
        diamonds()
    }

    async function linesHeight() {
        const linesList = preloader.querySelectorAll('[data-js="preloaderLine"]')
        const duration = parseFloat(window.getComputedStyle(linesList[0]).transitionDuration) * 1000;
        const animOrder = [2,6,4,1,9,5,0,8,3,7]
        const video = logo.querySelector('video')
        const img = logo.querySelector('img')

        await delay(1000)

        video.pause()
        video.currentTime = 0;
        video.style.opacity = '1'
        img.removeAttribute('style')
        img.style.transitionDuration = '0s'
        img.style.position = 'relative'
        img.style.top = '4.8%'
        img.style.scale = '0.767'
        img.style.opacity = 1
        await delay(200)
        video.play()

        await delay(3000)
        video.style.transitionDuration = '0.3s'
        video.style.opacity = '0'
        
        await delay(300)
        
        img.style.transitionDuration = '3s'
        img.style.transitionProperty = 'all'
        img.style.top = '0'
        img.style.scale = '1'
        logo.setAttribute('class', 'preloader__logo preloader__logo--middle')

        for(i = 0; i < animOrder.length; i++) {
            linesList[animOrder[i]].classList.add('preloader__line--hidden')

            if(i < 3) {
                await delay(duration * 0.05)
            } else if (i > 3 && i < animOrder.length - 1) {
                await delay(duration * 0.02)
            }
        }

        const preloaderBg = preloader.querySelector('[data-js="preloaderBg"]')

        if(preloaderBg) {
            preloaderBg.classList.remove('preloader__bg--start')
        }

        linesList[animOrder[animOrder.length - 1]].addEventListener('transitionend', () => {
            elsHeight()
            logoSize()
        }, { once: true })

    }

    function logoSize() {
        if(!logo) return

        logo.setAttribute('class', 'preloader__logo')

        logo.addEventListener('transitionend', async function() {
            await delay(500)
            diamonds()
        }, {once: true})
    }

    function elsHeight() {
        const els = preloader.querySelectorAll('[data-js="heightAnim"]')

        els.forEach(el => {
            heightAnim(el, '1s')
        })
    }

    function diamonds() {
        const figures = document.querySelectorAll('[data-js="preloaderMaskFigure"]')
        const svg = preloader.querySelector('[data-js="preloaderSVG"]')
        const vw = window.innerWidth
        const vh = window.innerHeight
        const fullWidth = 2759
        const innerWidth = fullWidth * 0.18
        const targetScale = vw >= vh ? Math.ceil(vw * 1.5 / innerWidth) : Math.ceil(vh * 1.5 / innerWidth)

        figures[0].addEventListener('transitionend', () => {
            preloader.remove();
            figures[0].closest('svg').remove();
            unlockBody();
            AOS.init({
                once: true
            });
            homeIntroAnim();
            solutionIntroAnim();
            cookieInit();
        }, {once: true})
    
        figures.forEach(async (figure, i) => {

            figure.style.translate = `${(vw - fullWidth * targetScale) / 2}px ${(vh - fullWidth * targetScale) / 2}px`

            figure.style.scale = `${targetScale}`

            if(i == 0) {
                svg.style.scale = `${targetScale}`
            }

            await delay(700)
            if(i == 0) {
                figure.style.opacity = 1
                svg.style.opacity = 1
            }

        })

        


    }

}
function homeIntroAnim() {
    const homeIntro = document.querySelector('[data-js="homeIntro"]')

    if(!homeIntro) return

    const menuItemsList = document.querySelector('[data-js="siteHeader"]')?.querySelectorAll('[data-js="mainMenuItem"][data-aos]')
    const slider = homeIntro.querySelector('[data-js="sectionBgSlider"]')
    const vw = window.innerWidth
    const vwPoint = 1320

    if(menuItemsList.length > 0 && vw > vwPoint) {
        menuItemsList[Math.ceil(menuItemsList.length / 2)].addEventListener('transitionend', hiAnim, {once: true})
    } else {
        hiAnim()
    }

    async function hiAnim() {
        const title = homeIntro.querySelector('[data-js="homeIntroTitle"]')
        const subtitle = homeIntro.querySelector('[data-js="homeIntroSubtitle"]')
        const btn = homeIntro.querySelector('[data-js="homeIntroBtn"]')
        const separator = homeIntro.querySelector('[data-js="homeIntroSeparator"]')

        opacityAnim(title)

        await delay(600)

        opacityAnim(subtitle)

        await delay(600)

        commonAnimation(separator)
        commonAnimation(btn)

        if(slider) {
            slider.swiper.params.autoplay = {
                delay: 3000,
            };

            slider.swiper.autoplay.start();
        }
    }
}
function homeCatalogAnim() {
    const homeCatalogs = document.querySelectorAll('[data-js="homeCatalog"]')

    if(homeCatalogs.length < 1) return

    
    homeCatalogs.forEach((homeCatalog, i) => {
        const currentId = `homeCatalog${i+1}`
        const cardsList = homeCatalog.querySelector('[data-js="homeCatalogList"]')?.querySelectorAll('[data-js="catalogCard"]')
        
        homeCatalog.setAttribute('data-anim-id', currentId)
        
        if(cardsList.length > 0) {
            cardsList.forEach((card, i) => {
                switch (i) {
                    case 0:
                        setAttributes(card, {
                            'data-aos': 'fade-up',
                            'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                            'data-aos-duration': '600',
                            'data-aos-anchor-placement': 'top-center'
                        })
                        break
                    case 1:
                    case 2:
                        setAttributes(card, {
                            'data-aos': 'fade-up',
                            'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                            'data-aos-duration': '600',
                            'data-aos-delay': `${i * 200 + 400}`,
                            'data-aos-anchor-placement': 'top-center'
                        })
                        break
                    case 3:
                    case 4:
                        setAttributes(card, {
                            'data-aos': 'fade-up',
                            'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                            'data-aos-duration': '600',
                            'data-aos-delay': `${i * 200 - 400}`,
                            'data-aos-anchor-placement': 'top-center'
                        })
                        break
                    default:
                        setAttributes(card, {
                            'data-aos': 'fade-up',
                            'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                            'data-aos-duration': '600',
                            'data-aos-delay': `${i * 200}`,
                            'data-aos-anchor-placement': 'top-center'
                        })
                }
                    
                if(i === cardsList.length - 1) {
                    const cardDelay = card.getAttribute('data-aos-delay') ? parseInt(card.getAttribute('data-aos-delay')) : 0
                    const tabsBlockList = homeCatalog.querySelector('[data-js="tabsBlockList"]')
                    
                    cardsList.forEach(card => {
                        const cardTitle = card.querySelector('[data-js="catalogCardTitle"]')

                        if(cardTitle) {
                            setAttributes(cardTitle, {
                                'data-aos': 'fade-up',
                                'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                                'data-aos-duration': '500',
                                'data-aos-delay': `${cardDelay}`,
                            'data-aos-anchor-placement': 'top-center'
                            })
                        }
                    })

                    setAttributes(tabsBlockList, {
                        'data-aos': 'fade-up',
                        'data-aos-anchor': `[data-anim-id="${currentId}"]`,
                        'data-aos-duration': '600',
                        'data-aos-delay': `${cardDelay}`,
                            'data-aos-anchor-placement': 'top-center'
                    })
                    
                }
                    
            })
        }
                  
    })
}
function sAboutAnim() {
    const sAbouts = document.querySelectorAll('[data-js="sAbout"]')

    if(sAbouts.length < 1) return

    sAbouts.forEach(sAbout => {
        const video = sAbout.querySelector('[data-js="sAboutVideo"]');
        const maskBg = sAbout.querySelector('[data-js="sAboutMaskBg"]');
        const rect = sAbout.querySelector('[data-js="sAboutRect"]');
        const text = sAbout.querySelector('[data-js="sAboutText"]');
        const title = sAbout.querySelector('[data-js="sAboutTitle"]');
        const cards = sAbout.querySelectorAll('[data-js="sAboutCard"]');
        const logo = sAbout.querySelector('[data-js="sAboutLogo"]');
        const pathList = logo.querySelectorAll('[data-anim-type="opacityUp100"]')

        maskBg?.setAttribute('height', `${sAbout.offsetHeight + 5}px`)

        if(video) {
            const videoAnimEl = video.querySelector('[data-anim-type]')

            if(videoAnimEl) {
                video.addEventListener('transitionend', () => {
                    videoAnimEl.classList.add('animated')
                }, {once: true})

                text?.setAttribute('data-aos-delay', '2000')
                if(cards.length) {
                    [...cards].reverse().forEach((card, i) => {
                        card.setAttribute('data-aos-delay', `${2800 - i * 100}`)
                    })
                }
            }

            if(rect && videoAnimEl) {
                const rectWidth = rect.getAttribute('width')
                const rectHeight = rect.getAttribute('height')
                rect.setAttribute('width', '1px')
                rect.setAttribute('height', '0')
                videoAnimEl.addEventListener('transitionend', async function() {
                    rect.setAttribute('height', rectHeight)
                    await delay(600)
                    rect.setAttribute('width', rectWidth)
                }, {once: true})
            }

            if(text) {
                text.addEventListener('transitionstart', function() {
                    if(title) {
                        opacityAnim(title)
                    }
                }, {once: true})
            }

            if(logo) {
                if(cards.length > 0) {
                    cards[0].addEventListener('transitionend', async function() {
                        for(let i = 0; i < pathList.length; i++) {
                            await delay(100)
                            opacityAnim(pathList[i])
                        }
                    })
                } else if(title) {
                    title.addEventListener('transitionend', async function() {
                        for(let i = 0; i < pathList.length; i++) {
                            await delay(100)
                            opacityAnim(pathList[i])
                        }
                    })
                }
            }
        }
    })
}
